        for i in range(m):
            vi = small_vals[i]
            for j in range(i + 1, m):
                vj = small_vals[j]
                if vi > vj:
                    vi, vj = vj, vi
                # Quick rejection: if vi * vj > threshold * vi, then lcm > threshold
                if vi * vj > threshold * vi:
