    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        if n == 1:
            return 1
        def can(L: int) -> bool:
            INF = 10**9
            # dp[c][len] = min flips up to current pos with last char c and run len
            dp0 = [INF] * (L + 1)
            dp1 = [INF] * (L + 1)
            # first char
            for c in (0,1):
                flips = 0 if (s[0] == '0' and c==0) or (s[0]=='1' and c==1) else 1
                if c==0:
