        H.append(h)

    def visible(h0: float) -> bool:
        max_slope = -1e30
        for x, h in zip(X, H):
            slope = (h - h0) / x
            if slope <= max_slope:
                return False
            if slope > max_slope:
                max_slope = slope
        return True

    # Check at height 0
    if visible(0.0):
        print(-1)
        return

    # Binary search for threshold where visibility turns true
    lo = 0.0
    hi = max(H) * 2.0  # upper bound large enough
    for _ in range(80):
        mid = (lo + hi) / 2
        if visible(mid):
            hi = mid
        else:
            lo = mid

    # lo is the maximum height where visibility is still false
    print(f"{lo:.18f}")

if __name__ == "__main__":
