import sys

def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    try:
        N = int(next(it))
    except StopIteration:
        return
    K = int(next(it))
    X = int(next(it))
    T = [int(next(it)) for _ in range(N)]
    pref = [0] * (N + 1)
    for i in range(N):
        pref[i + 1] = pref[i] + T[i]

    # dp[i] : dict of last shipment day -> minimal cost for first i orders
    dp = [dict() for _ in range(N + 1)]
    dp[0][0] = 0  # no shipment yet, last day 0

    for i in range(1, N + 1):
        cur = {}
        for j in range(max(0, i - K), i):
            size = i - j
            sumT = pref[i] - pref[j]
            maxT = T[i - 1]  # since T is non-decreasing
            for last_day, cost in dp[j].items():
                S = last_day + X
                if S < maxT:
                    S = maxT
                new_cost = cost + size * S - sumT
                if S not in cur or new_cost < cur[S]:
                    cur[S] = new_cost
        dp[i] = cur

    ans = min(dp[N].values())
    print(ans)

if __name__ == "__main__":
