class Solution:
    def subsequencePairCount(self, nums: List[int]) -> int:
        n = len(nums)
        # count subsets by gcd
        freq = {}
        for mask in range(1, 1<<n):
            cur_g = 0
            for i in range(n):
                if mask>>i & 1:
                    cur_g = gcd(cur_g, nums[i])
            freq[cur_g] = freq.get(cur_g, 0) + 1
        res = 0
        for cnt in freq.values():
            res = (res + cnt*cnt) % MOD
        return res
