            # decrement counts along this word's path
            for node in path[1:]:
                node.cnt -= 1
            # find deepest node where cnt >= k
            depth = 0
            for i, node in enumerate(path[1:], 1):
                if node.cnt >= k:
                    depth = i
                else:
                    break
            ans.append(depth)
            # restore counts
            for node in path[1:]:
                node.cnt += 1
        return ans
